func (t AssistantCard) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"kind"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t AssistantCard) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "create":
		return t.AsCreateCard()
	case "memory":
		return t.AsMemoryCard()
	case "reschedule":
		return t.AsRescheduleCard()
	case "sleep":
		return t.AsSleepCard()
	case "update":
		return t.AsUpdateCard()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

